-- Pity is Velvet or better every 15 cracks. A silk or satin pull is refused while a better treasure remains.
CREATE OR REPLACE FUNCTION public.vault_note_pull(p_user_id uuid, p_item_id text)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_pity integer;
  v_rarity text;
  v_kind text;
BEGIN
  SELECT rarity, kind INTO v_rarity, v_kind FROM public.collectible_items WHERE id = p_item_id AND active;
  IF v_rarity IS NULL THEN
    RAISE EXCEPTION 'UNKNOWN_ITEM';
  END IF;
  INSERT INTO public.user_vault_state (user_id) VALUES (p_user_id) ON CONFLICT (user_id) DO NOTHING;
  SELECT cracks_since_velvet INTO v_pity FROM public.user_vault_state WHERE user_id = p_user_id FOR UPDATE;
  IF v_rarity IN ('silk', 'satin') AND COALESCE(v_pity, 0) >= 14 AND EXISTS (
    SELECT 1 FROM public.collectible_items ci
    WHERE ci.active AND ci.rarity IN ('velvet', 'forbidden', 'obsession')
      AND NOT EXISTS (
        SELECT 1 FROM public.user_collectibles uc
        WHERE uc.user_id = p_user_id AND uc.item_id = ci.id
      )
  ) THEN
    RAISE EXCEPTION 'PITY_DUE';
  END IF;
  IF v_rarity IN ('velvet', 'forbidden', 'obsession') THEN
    v_pity := 0;
  ELSE
    v_pity := COALESCE(v_pity, 0) + 1;
  END IF;
  UPDATE public.user_vault_state SET cracks_since_velvet = v_pity WHERE user_id = p_user_id;

  INSERT INTO public.user_vault_rewards (user_id, category, title, badge)
  SELECT p_user_id, r.category, r.title, r.badge
  FROM public.vault_category_rewards r
  WHERE r.category = v_kind
    AND NOT EXISTS (
      SELECT 1 FROM public.collectible_items missing
      WHERE missing.kind = v_kind AND missing.active
        AND NOT EXISTS (
          SELECT 1 FROM public.user_collectibles uc
          WHERE uc.user_id = p_user_id AND uc.item_id = missing.id
        )
    )
  ON CONFLICT (user_id, category) DO NOTHING;

  RETURN v_pity;
END;
$$;
REVOKE ALL ON FUNCTION public.vault_note_pull(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.vault_note_pull(uuid, text) TO service_role;

-- Charge and grant happen in one transaction. Failure rolls the credit back.
CREATE OR REPLACE FUNCTION public.velvet_commit_open(
  p_user_id uuid,
  p_item_id text,
  p_cost integer,
  p_roll double precision,
  p_odds jsonb,
  p_skip_charge boolean
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  bal integer;
  owner boolean;
BEGIN
  IF p_cost < 1 OR p_cost > 200 THEN
    RAISE EXCEPTION 'BAD_COST';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.collectible_items WHERE id = p_item_id AND active) THEN
    RAISE EXCEPTION 'UNKNOWN_ITEM';
  END IF;
  IF EXISTS (SELECT 1 FROM public.user_collectibles WHERE user_id = p_user_id AND item_id = p_item_id) THEN
    RAISE EXCEPTION 'ALREADY_OWNED';
  END IF;

  SELECT credits, COALESCE(is_catalog_owner, false) INTO bal, owner
  FROM public.profiles WHERE user_id = p_user_id FOR UPDATE;

  IF NOT p_skip_charge AND NOT COALESCE(owner, false) THEN
    IF COALESCE(bal, 0) < p_cost THEN
      RAISE EXCEPTION 'NEED_CREDITS';
    END IF;
    UPDATE public.profiles
      SET credits = credits - p_cost
      WHERE user_id = p_user_id AND credits >= p_cost
      RETURNING credits INTO bal;
    IF bal IS NULL THEN
      RAISE EXCEPTION 'NEED_CREDITS';
    END IF;
  END IF;

  INSERT INTO public.user_collectibles (user_id, item_id) VALUES (p_user_id, p_item_id);
  PERFORM public.vault_note_pull(p_user_id, p_item_id);
  INSERT INTO public.box_opens (user_id, item_id, cost, charged, roll, odds)
  VALUES (
    p_user_id,
    p_item_id,
    p_cost,
    CASE WHEN p_skip_charge OR COALESCE(owner, false) THEN 0 ELSE p_cost END,
    p_roll,
    p_odds
  );
  RETURN jsonb_build_object('credits', COALESCE(bal, 0), 'item_id', p_item_id);
END;
$$;

REVOKE ALL ON FUNCTION public.velvet_commit_open(uuid, text, integer, double precision, jsonb, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.velvet_commit_open(uuid, text, integer, double precision, jsonb, boolean) TO service_role;

-- One charge for several treasures. Any failure returns the credits.
CREATE OR REPLACE FUNCTION public.velvet_commit_bundle(
  p_user_id uuid,
  p_item_ids text[],
  p_cost integer,
  p_rolls jsonb,
  p_odds jsonb,
  p_skip_charge boolean
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  bal integer;
  owner boolean;
  v_item text;
  idx integer := 0;
BEGIN
  IF p_item_ids IS NULL OR cardinality(p_item_ids) < 2 THEN
    RAISE EXCEPTION 'BAD_BUNDLE';
  END IF;
  IF p_cost < 1 OR p_cost > 200 THEN
    RAISE EXCEPTION 'BAD_COST';
  END IF;
  IF (SELECT COUNT(DISTINCT id) FROM unnest(p_item_ids) AS id) <> cardinality(p_item_ids) THEN
    RAISE EXCEPTION 'DUP_DRAW';
  END IF;

  SELECT credits, COALESCE(is_catalog_owner, false) INTO bal, owner
  FROM public.profiles WHERE user_id = p_user_id FOR UPDATE;

  IF NOT p_skip_charge AND NOT COALESCE(owner, false) THEN
    IF COALESCE(bal, 0) < p_cost THEN
      RAISE EXCEPTION 'NEED_CREDITS';
    END IF;
    UPDATE public.profiles
      SET credits = credits - p_cost
      WHERE user_id = p_user_id AND credits >= p_cost
      RETURNING credits INTO bal;
    IF bal IS NULL THEN
      RAISE EXCEPTION 'NEED_CREDITS';
    END IF;
  END IF;

  FOREACH v_item IN ARRAY p_item_ids LOOP
    idx := idx + 1;
    IF NOT EXISTS (SELECT 1 FROM public.collectible_items WHERE id = v_item AND active) THEN
      RAISE EXCEPTION 'UNKNOWN_ITEM';
    END IF;
    IF EXISTS (SELECT 1 FROM public.user_collectibles WHERE user_id = p_user_id AND item_id = v_item) THEN
      RAISE EXCEPTION 'ALREADY_OWNED';
    END IF;
    INSERT INTO public.user_collectibles (user_id, item_id) VALUES (p_user_id, v_item);
    PERFORM public.vault_note_pull(p_user_id, v_item);
    INSERT INTO public.box_opens (user_id, item_id, cost, charged, roll, odds)
    VALUES (
      p_user_id,
      v_item,
      p_cost,
      CASE WHEN idx = 1 AND NOT p_skip_charge AND NOT COALESCE(owner, false) THEN p_cost ELSE 0 END,
      COALESCE((p_rolls ->> (idx - 1))::double precision, 0),
      p_odds
    );
  END LOOP;

  RETURN jsonb_build_object('credits', COALESCE(bal, 0), 'item_ids', to_jsonb(p_item_ids));
END;
$$;

REVOKE ALL ON FUNCTION public.velvet_commit_bundle(uuid, text[], integer, jsonb, jsonb, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.velvet_commit_bundle(uuid, text[], integer, jsonb, jsonb, boolean) TO service_role;

-- One credit for a user-triggered post. Failure rolls the credit back. Never spends free studio tries.
CREATE OR REPLACE FUNCTION public.velvet_commit_post(
  p_user_id uuid,
  p_companion_id text,
  p_caption text,
  p_image_url text,
  p_skip_charge boolean
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  bal integer;
  owner boolean;
  post_id uuid;
  caption text;
BEGIN
  IF p_companion_id IS NULL OR length(btrim(p_companion_id)) < 1 OR length(p_companion_id) > 128 THEN
    RAISE EXCEPTION 'BAD_POST';
  END IF;
  IF p_image_url IS NULL OR length(btrim(p_image_url)) < 8 OR length(p_image_url) > 8000 THEN
    RAISE EXCEPTION 'BAD_POST';
  END IF;
  caption := left(btrim(COALESCE(p_caption, '')), 280);
  IF caption = '' THEN
    caption := 'For you.';
  END IF;

  SELECT credits, COALESCE(is_catalog_owner, false) INTO bal, owner
  FROM public.profiles WHERE user_id = p_user_id FOR UPDATE;

  IF NOT p_skip_charge AND NOT COALESCE(owner, false) THEN
    IF COALESCE(bal, 0) < 1 THEN
      RAISE EXCEPTION 'NEED_CREDITS';
    END IF;
    UPDATE public.profiles
      SET credits = credits - 1
      WHERE user_id = p_user_id AND credits >= 1
      RETURNING credits INTO bal;
    IF bal IS NULL THEN
      RAISE EXCEPTION 'NEED_CREDITS';
    END IF;
  END IF;

  INSERT INTO public.companion_posts (user_id, companion_id, caption, image_url, credits)
  VALUES (
    p_user_id,
    btrim(p_companion_id),
    caption,
    btrim(p_image_url),
    CASE WHEN p_skip_charge OR COALESCE(owner, false) THEN 0 ELSE 1 END
  )
  RETURNING id INTO post_id;

  RETURN jsonb_build_object('credits', COALESCE(bal, 0), 'post_id', post_id);
END;
$$;

